class StringPool {
public:
	// 获取或创建字符串
	std::string* getString(std::string& str) {
		// 查找是否已经缓存了这个字符串
		auto it = pool.find(str);
		if (it != pool.end()) {
			return &it->second; // 返回缓存中的字符串
		}

		// 如果没有缓存，创建新字符串并加入缓存池
		pool[str] = str;
		return &pool[str];
	}

private:
	// 使用 unordered_map 来存储缓存的字符串
	std::unordered_map<std::string, std::string> pool;
};

StringPool stringPool;

class ObjectPool {
private:
	std::vector<std::string*> pool;

public:
	ObjectPool(int initialSize) {
		for (int i = 0; i < initialSize; ++i) {
			pool.push_back(new std::string());
		}
	}

	~ObjectPool() {
		for (auto obj : pool) {
			delete obj;
		}
	}

	std::string* getObject() {
		if (pool.empty()) {
			std::cout << "No objects available!" << std::endl;
			return nullptr;
		}
		std::string* obj = pool.back();
		pool.pop_back();
		return obj;
	}

	void returnObject(std::string* obj) {
		pool.push_back(obj);
	}
};
ObjectPool pool(256);

