void* operator new(size_t size) {
	//谁调用了我
	//std::cout << "谁调用了我" << std::hex << *(int*)((int)&size - 4) << std::endl;
	// 为了能够存储大小信息，我们在实际分配内存之前
	// 为大小存储留出空间
	void* ptr = std::malloc(size + sizeof(size_t));  // 多分配一个大小字段
	if (!ptr) {
		throw std::bad_alloc();
	}
	*reinterpret_cast<size_t*>(ptr) = size;  // 将大小存储在分配的内存块之前
	return reinterpret_cast<void*>(reinterpret_cast<size_t*>(ptr) + 1);
}

void operator delete(void* ptr) noexcept {
	if (ptr) {
		size_t* realPtr = reinterpret_cast<size_t*>(ptr) - 1;
		size_t size = *realPtr;  // 获取分配时的大小信息
		//std::cout << "Freeing " << size << " bytes of memory." << std::endl;
		std::free(realPtr);
	}
}

