//窗口消息事件处理函数
LRESULT __stdcall sub_47E7B6(HWND hWnd, UINT Msg, WPARAM wParam, LPARAM lParam)
{
	sub_446497((int*)byte_4B9B10, 240, 32);
	sub_47EFA0((char*)byte_4B9B10);
	//内部都只是在简单赋值
	if (Msg > 6)//键盘消息
	{
		if (Msg == 32)
		{
			SetCursor(0);
			return 1;
		}
		if (Msg == 256)//键盘消息
		{
			switch (wParam)
			{
				//关闭游戏消息，esc，F12
			case 0x1Bu:
			case 0x7Bu:
				PostMessageA(hWnd, 0x10u, 0, 0);
				break;
			case 0x70u://F1
				sub_453B66((int)byte_4B9B10);//重启启动游戏，回到初始标题
				break;
			case 0x71u://F2
				dword_4B93A8 = dword_4B93A8 == 0;//是否绘制碰撞框
				break;
				//F3
			case 0x72u:
				sub_4685F6((int*)byte_4B9B10);//开启或关闭录制
				break;
			case 0x73u://F4
				sub_468667((int)byte_4B9B10);//开启播放录制内容
				break;
				//F7
			case 0x78u:
				if (byte_4B91D9)//是否处于调试模式
					byte_4B91D1 = 1;
				break;
			case 0x7Au:// 处理F10键
				if (byte_4B91D9)//是否处于调试模式
					dword_4B91D4 = dword_4B91D4 == 0;
				break;
			default:
				return DefWindowProcA(hWnd, Msg, wParam, lParam);
			}
		}
	}
	else if (Msg == 6)//鼠标点击消息
	{
		//获得窗口焦点
		if (wParam)
		{
			dword_4B99F8 = 1;
			sub_4A1376((char*)byte_4BDC60, 0);
			if (!byte_4B99E6)//是否运行后台运行，不允许后台才可进入if
			{
				dword_4B99EC = 1;//如果获取焦点的时候，且程序设置又是不允许后台运行，该值为1，失去焦点又不允许后台允许该值为0
				if (!sub_47EF80((int*)byte_4B9B10))
					sub_440BC2((int)byte_4BDB28);
			}
		}
		else //失去窗口焦点
		{
			/*
			dword_4B99F8 = 0;
			sub_4A1376((char*)byte_4BDC60, 1);

			if (!byte_4B99E6)//是否运行后台运行，不允许后台才可进入if
			{
				dword_4B99EC = 0;//如果获取焦点的时候，且程序设置又是不允许后台运行，该值为1，失去焦点又不允许后台允许该值为0
				sub_440B78((int)byte_4BDB28);
			}
			*/
		}
	}
	else if (Msg != 1 && Msg == 2)
	{
		PostQuitMessage(0);
	}
	return DefWindowProcA(hWnd, Msg, wParam, lParam);
}


